import type { Metadata } from "next";
import Link from "next/link";
import { notFound, redirect } from "next/navigation";
import { updateVendorProduct } from "@/src/actions/vendor";
import { getCurrentUserProfile } from "@/src/lib/auth";
import { prisma } from "@/src/lib/prisma";
import { requireCompanyManager } from "@/src/lib/vendor";

export const dynamic = "force-dynamic";
export const metadata: Metadata = { title: "Edit Product Profile", robots: { index: false, follow: false } };
type Props = { params: Promise<{ slug: string }>; searchParams: Promise<{ saved?: string }> };
export default async function VendorProductPage({ params, searchParams }: Props) { const user = await getCurrentUserProfile(); if (!user) redirect("/sign-in?redirect_url=%2Fvendor"); const product = await prisma.product.findUnique({ where: { slug: (await params).slug }, include: { company: true } }); if (!product) notFound(); if (!(await requireCompanyManager(user.id, product.companyId))) redirect("/vendor"); const saved = (await searchParams).saved === "true"; return <main className="mx-auto max-w-3xl px-4 py-12"><Link href="/vendor" className="text-caption font-semibold text-accent">← Vendor Dashboard</Link><h1 className="mt-6 text-h1 text-text-primary">Edit {product.name}</h1><p className="mt-2 text-body text-text-secondary">Company-provided information is displayed separately from independent research and evidence.</p>{saved && <p className="mt-5 rounded-lg border border-border bg-bg-elevated p-3 text-body text-text-secondary">Product profile saved.</p>}<form action={updateVendorProduct} className="mt-8 grid gap-5"><input type="hidden" name="productId" value={product.id} /><TextArea label="Description" name="description" value={product.description ?? ""} /><Field label="Short description" name="shortDescription" value={product.shortDescription ?? ""} /><Field label="Official product URL" name="website" type="url" value={product.website ?? ""} required={false} /><Field label="Product image URL" name="imageUrl" type="url" value={product.imageUrl ?? ""} required={false} /><TextArea label="Company-provided specifications and claims" name="vendorProvidedInfo" value={product.vendorProvidedInfo ?? ""} required={false} /><button className="w-fit rounded-md bg-text-primary px-4 py-2 text-caption font-semibold text-bg">Save product profile</button></form></main>; }
function Field({ label, name, value, type = "text", required = true }: { label: string; name: string; value: string; type?: string; required?: boolean }) { return <label className="grid gap-1 text-caption font-medium text-text-secondary">{label}<input name={name} type={type} required={required} defaultValue={value} className="rounded-md border border-border bg-bg px-3 py-2 text-body text-text-primary focus:border-accent focus:outline-none" /></label>; }
function TextArea({ label, name, value, required = true }: { label: string; name: string; value: string; required?: boolean }) { return <label className="grid gap-1 text-caption font-medium text-text-secondary">{label}<textarea name={name} required={required} minLength={required ? 20 : undefined} rows={7} defaultValue={value} className="rounded-md border border-border bg-bg px-3 py-2 text-body text-text-primary focus:border-accent focus:outline-none" /></label>; }
